// MT2009_PLUS_SPIRALA_CZASU_V2 (clock) (server-patches/spiralaclock): q.set_clock_of(quest, name, seconds) - the
// clock of ANOTHER quest's letter, as q.set_title2 does for its title. Spirala Czasu (spirala_czasu.quest) cuts
// the Biologist's / the stable keeper's / a relic's wait while its own quest runs, and q.set_clock would only
// touch the spiral's own state: this one stores the clock in that quest's state and sends the client a
// QuestInfo update (clock name + value) right away, so the letter and the quest window count down from the
// new time at once. Sent only while the quest's letter is on the client (bStart - q.start / send_letter, not
// cleared by q.done): an update of an unknown index would make the client an empty quest. Returns whether
// it was sent.
bool PC::M2SetQuestClock(const string& quest, const string& name, int value)
{
	const unsigned int qi = CQuestManager::instance().GetQuestIndexByName(quest);
	QuestInfo::iterator it = qi ? m_QuestInfo.find(qi) : m_QuestInfo.end();
	if (it == m_QuestInfo.end())
		return false;
	it->second._clock_name = name;
	it->second._clock_value = value;
	LPCHARACTER ch = CQuestManager::instance().GetCurrentCharacterPtr();
	if (!it->second.bStart || !it->second.iIndex || !ch || !ch->GetDesc() || ch->GetPlayerID() != GetID())
		return false;

	QuestState* old = m_RunningQuestState;
	const int old2 = m_iSendToClient;
	m_RunningQuestState = &it->second;
	m_iSendToClient = QUEST_SEND_CLOCK_NAME | QUEST_SEND_CLOCK_VALUE;
	SendQuestInfoPakcet();
	m_RunningQuestState = old;
	m_iSendToClient = old2;
	return true;
}

