// MT2009_PLUS_SPIRALA_CZASU_V2 (lua) (server-patches/spiralaclock): q.set_clock_of(quest name, clock name, seconds) -
// another quest's letter clock, sent to the client at once (PC::M2SetQuestClock); true when sent.
ALUA(quest_m2_set_clock_of)
{
	PC* pPC = CQuestManager::instance().GetCurrentPC();
	if (!pPC || !lua_isstring(L, 1) || !lua_isstring(L, 2) || !lua_isnumber(L, 3))
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	lua_pushboolean(L, pPC->M2SetQuestClock(lua_tostring(L, 1), lua_tostring(L, 2), (int)rint(lua_tonumber(L, 3))) ? 1 : 0);
	return 1;
}

